// Synthex Pro — Default Plasma Layout
// Generated by Synthex Desktop Profile

var plasma = getApi("plasma");
var desktop = getApi("desktop");
var workspace = getApi("workspace");

// ── Panel ──
var panel = new Panel;
panel.location = "left";
panel.height = 48;
panel.alignment = "center";
panel.opacity = 0.9;

// Add widgets
panel.addWidget("org.kde.plasma.kickoff");
var spacer = panel.addSpacer();
panel.addWidget("org.kde.plasma.pager");
panel.addWidget("org.kde.plasma.systemtray");
panel.addWidget("org.kde.plasma.digitalclock");

// ── Wallpaper ──
desktop.wallpaperPlugin = "org.kde.image";
desktop.currentConfigGroup = ["Wallpaper", "org.kde.image", "General"];
desktop.writeConfig("Image", "/usr/share/wallpapers/synthex-graphite.png");

// ── Window Behavior ──
workspace.currentConfigGroup = ["Windows", "Focus"];
workspace.writeConfig("FocusPolicy", "ClickFocus");
workspace.currentConfigGroup = ["Compositing"];
workspace.writeConfig("Backend", "opengl");
workspace.writeConfig("AnimationSpeed", "2");
workspace.writeConfig("Enabled", "true");

print("Synthex Pro profile applied");
